// app.js - Development source
// This is the original source file for debugging purposes

(function() {
    // Update logo text
    const LOGO_TEXT = "// root@dev:~#";
    const logoElement = document.querySelector('.logo');
    if (logoElement) {
        logoElement.textContent = LOGO_TEXT;
    }

    // Skill card interactions
    const skillCards = document.querySelectorAll('.skill-card');
    skillCards.forEach(card => {
        card.addEventListener('mouseenter', () => {
            card.style.transform = 'scale(1.05)';
            card.style.transition = 'transform 0.2s';
        });
        card.addEventListener('mouseleave', () => {
            card.style.transform = 'scale(1)';
        });
    });

    // Commit history interactions
    const commitItems = document.querySelectorAll('.commit-item');
    commitItems.forEach((item, index) => {
        item.addEventListener('click', () => {
            console.log(`📂 commit #${index + 1}: ${item.textContent.trim()}`);
        });
    });

    // Testimonials click effect
    const testimonials = document.querySelectorAll('.testimonial');
    testimonials.forEach(item => {
        item.addEventListener('click', function() {
            this.style.backgroundColor = '#1e2342';
            setTimeout(() => {
                this.style.backgroundColor = '';
            }, 200);
        });
    });

    // Button handler
    const hireButton = document.querySelector('.btn');
    if (hireButton) {
        hireButton.addEventListener('click', () => {
            const notification = document.createElement('div');
            notification.textContent = '🎉 application sent! (not really)';
            notification.style.position = 'fixed';
            notification.style.bottom = '20px';
            notification.style.right = '20px';
            notification.style.backgroundColor = '#4affb5';
            notification.style.color = '#0a0c1b';
            notification.style.padding = '1rem 2rem';
            notification.style.borderRadius = '40px';
            notification.style.fontWeight = 'bold';
            notification.style.zIndex = '9999';
            document.body.appendChild(notification);
            setTimeout(() => {
                document.body.removeChild(notification);
            }, 3000);
        });
    }

    // Navigation links
    const navLinks = document.querySelectorAll('.nav-links a');
    navLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            console.log(`🔗 navigation to: ${this.textContent} (coming soon)`);
            this.style.opacity = '0.5';
            setTimeout(() => {
                this.style.opacity = '1';
            }, 200);
        });
    });

    // Time reminder
    const logTime = () => {
        const now = new Date();
        const timeString = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`;
        console.log(`⏰ system time: ${timeString} - remember to go outside`);
    };
    setInterval(logTime, 10000);
    logTime();

    // Tips popup
    const showTip = () => {
        const tipElement = document.createElement('div');
        tipElement.textContent = '💡 pro tip: real developers break prod on Fridays';
        tipElement.style.position = 'fixed';
        tipElement.style.bottom = '80px';
        tipElement.style.right = '20px';
        tipElement.style.backgroundColor = '#1a1e36';
        tipElement.style.color = '#a0a8ff';
        tipElement.style.padding = '0.8rem 1.5rem';
        tipElement.style.borderRadius = '30px';
        tipElement.style.fontSize = '0.9rem';
        tipElement.style.border = '1px solid #4a3f7a';
        tipElement.style.zIndex = '9998';
        tipElement.style.opacity = '0';
        tipElement.style.transition = 'opacity 0.5s';
        
        document.body.appendChild(tipElement);
        
        setTimeout(() => {
            tipElement.style.opacity = '1';
        }, 100);
        
        setTimeout(() => {
            tipElement.style.opacity = '0';
            setTimeout(() => {
                document.body.removeChild(tipElement);
            }, 500);
        }, 5000);
    };
    
    setTimeout(showTip, 2000);
    setInterval(showTip, 30000);

    // Easter egg keyboard shortcut
    let eggCounter = 0;
    document.addEventListener('keydown', (e) => {
        if (e.key === 'd' && e.ctrlKey && e.shiftKey) {
            e.preventDefault();
            const messages = [
                '🚀 developer mode activated',
                '🐛 bug factory: online',
                '☕ coffee level: critical',
                '🔥 prod is safe... for now'
            ];
            eggCounter = (eggCounter + 1) % messages.length;
            console.log(messages[eggCounter]);
        }
    });

    // Copy protection humor
    const allElements = document.querySelectorAll('*');
    allElements.forEach(el => {
        el.addEventListener('copy', () => {
            console.log('📋 stealing code? at least make it look like yours');
        });
    });

    // Scroll tracking
    let scrolling = false;
    window.addEventListener('scroll', () => {
        if (!scrolling) {
            scrolling = true;
            setTimeout(() => {
                const shouldLog = Math.random() > 0.8;
                if (shouldLog) {
                    console.log("🔄 you're still here? hire me already");
                }
                scrolling = false;
            }, 200);
        }
    });

    // Add additional CSS
    const addStyles = () => {
        const styleTag = document.createElement('style');
        styleTag.textContent = `
            .skill-card:hover { 
                background: #2a2f4f; 
                border-color: #4affb5; 
                transition: all 0.2s; 
            } 
            .commit-item:hover { 
                background: #1e2342; 
                border-color: #4affb5; 
                transform: translateX(5px); 
                transition: all 0.2s; 
            } 
            .testimonial:hover { 
                border-color: #4affb5; 
                transform: translateY(-2px); 
                transition: all 0.2s; 
            }
        `;
        document.head.appendChild(styleTag);
    };
    addStyles();

    // Initial console messages
    console.log('✅ app.min.js loaded - have a nice day, nerd');
    console.log('📦 version: 0.0.1-alpha.0.1.final(2).test');
    console.log('🔧 current user: some dev');
})();